#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#define PORT 5004
unsigned checksum(const unsigned char*d,size_t n){unsigned long sum=0;for(size_t i=0;i<n;i+=2){unsigned w=(unsigned)d[i]<<8;if(i+1<n)w|=d[i+1];sum+=w;sum=(sum&0xffff)+(sum>>16);}return (~sum)&0xffff;}
int validbits(const char*s){if(!*s)return 0;for(;*s;s++)if(*s!='0'&&*s!='1')return 0;return 1;}
void crc_rem(const char*bits,const char*poly,char*out,int append){int n=strlen(bits),m=strlen(poly),len=n+(append?m-1:0);char w[4096];if(len>=4096){out[0]=0;return;}strcpy(w,bits);if(append)memset(w+n,'0',m-1);w[len]=0;for(int i=0;i<=len-m;i++)if(w[i]=='1')for(int j=0;j<m;j++)w[i+j]=(w[i+j]==poly[j]?'0':'1');strcpy(out,w+len-(m-1));}
void hamming(const char*d,char*out){int m=strlen(d),r=0;while((1<<r)<m+r+1)r++;int n=m+r;char b[2048];memset(b,'0',n+1);int k=0;for(int p=1;p<=n;p++)if(p&(p-1))b[p]=d[k++];for(int p=1;p<=n;p*=2){int parity=0;for(int q=1;q<=n;q++)if((q&p)&&q!=p)parity^=b[q]-'0';b[p]=(char)('0'+parity);}for(int p=1;p<=n;p++)out[p-1]=b[p];out[n]=0;}
int main(void){char choice[16],msg[1024],data[1024],poly[256],code[2048],request[4096];puts("Choose: 1=Checksum, 2=CRC, 3=Hamming");printf("Choice: ");fgets(choice,sizeof(choice),stdin);if(choice[0]=='1'){printf("Message text: ");fgets(msg,sizeof(msg),stdin);msg[strcspn(msg,"\r\n")]=0;snprintf(request,sizeof(request),"CHECKSUM|%u|%s",checksum((unsigned char*)msg,strlen(msg)),msg);}else if(choice[0]=='2'){printf("Data bits (e.g. 1101): ");fgets(data,sizeof(data),stdin);data[strcspn(data,"\r\n")]=0;printf("Generator bits (e.g. 1011): ");fgets(poly,sizeof(poly),stdin);poly[strcspn(poly,"\r\n")]=0;if(!validbits(data)||!validbits(poly)||strlen(poly)<2){puts("Invalid bits/polynomial");return 1;}char rem[256];crc_rem(data,poly,rem,1);snprintf(code,sizeof(code),"%s%s",data,rem);printf("Transmitted CRC codeword: %s\n",code);snprintf(request,sizeof(request),"CRC|%s|%s",poly,code);}else if(choice[0]=='3'){printf("Data bits (e.g. 1011): ");fgets(data,sizeof(data),stdin);data[strcspn(data,"\r\n")]=0;if(!validbits(data)){puts("Invalid bits");return 1;}hamming(data,code);printf("Transmitted Hamming codeword: %s\nFlip a bit position (1-based; 0=no error): ",code);fgets(msg,sizeof(msg),stdin);int p=atoi(msg),n=strlen(code);if(p>0&&p<=n)code[p-1]=(code[p-1]=='0'?'1':'0');printf("Received codeword: %s\n",code);snprintf(request,sizeof(request),"HAMMING|%s",code);}else{puts("Invalid choice");return 1;}
 int s=socket(AF_INET,SOCK_STREAM,0);struct timeval tv={5,0};setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));struct sockaddr_in a={0};a.sin_family=AF_INET;a.sin_port=htons(PORT);inet_pton(AF_INET,"127.0.0.1",&a.sin_addr);if(connect(s,(struct sockaddr*)&a,sizeof(a))<0){perror("connect (start error_server first)");return 1;}struct timespec t1,t2;clock_gettime(CLOCK_MONOTONIC,&t1);send(s,request,strlen(request),0);int n=recv(s,msg,sizeof(msg)-1,0);clock_gettime(CLOCK_MONOTONIC,&t2);if(n>0)msg[n]=0;double sec=(t2.tv_sec-t1.tv_sec)+(t2.tv_nsec-t1.tv_nsec)/1e9;printf("Receiver: %s\nProcessing/round-trip time: %.2f ms\n",n>0?msg:"No response",sec*1000);close(s);return 0;}
